-- PostgreSQL twin of migrations/0079_price_alerts.sql, generated by scripts/sqlite_to_pg_migration.py

-- Tiered Vambi price alerts (هشدار قیمت سطح‌بندی‌شده). Every user watches and is alerted only at their OWN level
-- (consumer / org employee / organization buyer / contracted shop); sellers get "no longer the best offer" without
-- the competitor's price. The level is derived server-side from the account and re-checked on every run.
-- A buyer's watched item. organization_id is the organization whose price the watch follows (NULL = retail).
CREATE TABLE IF NOT EXISTS price_watches (
    id                 BIGSERIAL PRIMARY KEY,
    user_id            INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    product_id         INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    level              TEXT    NOT NULL CHECK (level IN ('consumer', 'employee', 'org_buyer', 'shop')),
    organization_id    INTEGER REFERENCES organizations(id) ON DELETE CASCADE,
    quantity           INTEGER NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 100000),
    target_price_minor BIGINT CHECK (target_price_minor IS NULL OR target_price_minor > 0),
    alert_types        TEXT    NOT NULL,
    sms_enabled        INTEGER NOT NULL DEFAULT 1 CHECK (sms_enabled IN (0, 1)),
    state_json         TEXT,
    checked_at         TEXT,
    last_notified_at   TEXT,
    active             INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    created_at         TEXT    NOT NULL,
    updated_at         TEXT    NOT NULL,
    CHECK ((level IN ('consumer') AND organization_id IS NULL) OR (level <> 'consumer' AND organization_id IS NOT NULL))
);

-- One watch per user, product and organization context (retail = 0).
CREATE UNIQUE INDEX IF NOT EXISTS ux_price_watches_user_product ON price_watches(user_id, product_id, COALESCE(organization_id, 0));

CREATE INDEX IF NOT EXISTS ix_price_watches_active ON price_watches(active, product_id);

-- Daily price per level for 90-day charts. scope 'retail' is the public retail price (organization_key = 0);
-- scope 'organization' is the price ONE organization sees at a quantity (its own contract included), keyed by it.
CREATE TABLE IF NOT EXISTS price_history_daily (
    id               BIGSERIAL PRIMARY KEY,
    product_id       INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    scope            TEXT    NOT NULL CHECK (scope IN ('retail', 'organization')),
    organization_key INTEGER NOT NULL DEFAULT 0,
    quantity         INTEGER NOT NULL DEFAULT 1,
    day              TEXT    NOT NULL,
    min_price_minor BIGINT,
    last_price_minor BIGINT,
    in_stock         INTEGER NOT NULL DEFAULT 0 CHECK (in_stock IN (0, 1)),
    updated_at       TEXT    NOT NULL,
    UNIQUE (product_id, scope, organization_key, quantity, day)
);

-- Seller buy-box state per product and level, so "no longer the best offer" fires once per transition.
CREATE TABLE IF NOT EXISTS price_alert_seller_state (
    id          BIGSERIAL PRIMARY KEY,
    supplier_id INTEGER NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,
    product_id  INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    level       TEXT    NOT NULL CHECK (level IN ('retail', 'organization')),
    offer_id    INTEGER,
    is_best     INTEGER NOT NULL DEFAULT 0 CHECK (is_best IN (0, 1)),
    updated_at  TEXT    NOT NULL,
    UNIQUE (supplier_id, product_id, level)
);

-- Every alert sent (in-site always; SMS batched). dedupe_key makes a rerun in the same hour a no-op.
CREATE TABLE IF NOT EXISTS price_alert_events (
    id          BIGSERIAL PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    product_id  INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    watch_id    INTEGER REFERENCES price_watches(id) ON DELETE SET NULL,
    supplier_id INTEGER REFERENCES suppliers(id) ON DELETE SET NULL,
    level       TEXT    NOT NULL,
    alert_type  TEXT    NOT NULL,
    dedupe_key  TEXT    NOT NULL UNIQUE,
    sms_text    TEXT    NOT NULL,
    sms_status  TEXT    NOT NULL DEFAULT 'none'
                CHECK (sms_status IN ('none', 'pending', 'sent', 'failed', 'skipped_item', 'skipped_cap', 'unavailable')),
    sms_id      INTEGER,
    created_at  TEXT    NOT NULL,
    day         TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_price_alert_events_user ON price_alert_events(user_id, sms_status, day);

CREATE INDEX IF NOT EXISTS ix_price_alert_events_supplier ON price_alert_events(supplier_id, created_at);

-- One digest SMS per user per run hour (idempotency) and the global daily cap's counter.
CREATE TABLE IF NOT EXISTS price_alert_sms (
    id          BIGSERIAL PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    run_hour    TEXT    NOT NULL,
    day         TEXT    NOT NULL,
    item_count  INTEGER NOT NULL,
    status      TEXT    NOT NULL CHECK (status IN ('sending', 'sent', 'failed')),
    created_at  TEXT    NOT NULL,
    UNIQUE (user_id, run_hour)
);

CREATE INDEX IF NOT EXISTS ix_price_alert_sms_day ON price_alert_sms(day, status);
